using System;
using System.Net;

public class SsrfGuard
{
    public static bool IsSafePublicUrl(string urlString)
    {
        if (!Uri.TryCreate(urlString, UriKind.Absolute, out var uri))
            return false;

        if (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps)
            return false;

        try
        {
            var addresses = Dns.GetHostAddresses(uri.Host);
            foreach (var ip in addresses)
            {
                if (IPAddress.IsLoopback(ip)) return false;

                byte[] bytes = ip.GetAddressBytes();
                if (bytes.Length == 4) // IPv4 check
                {
                    // 10.0.0.0/8
                    if (bytes[0] == 10) return false;

                    // 172.16.0.0/12
                    if (bytes[0] == 172 && (bytes[1] >= 16 && bytes[1] <= 31)) return false;

                    // 192.168.0.0/16
                    if (bytes[0] == 192 && bytes[1] == 168) return false;

                    // 169.254.0.0/16 (Link Local / Cloud Metadata)
                    if (bytes[0] == 169 && bytes[1] == 254) return false;
                }
            }
            return true;
        }
        catch
        {
            return false;
        }
    }
}

public class Program
{
    public static void Main()
    {
        string safeUrl = "https://api.github.com/users/octocat";
        string maliciousSsrfUrl = "http://127.0.0.1:8080/admin/delete";
        string cloudMetadataUrl = "http://169.254.169.254/latest/meta-data/";

        Console.WriteLine($"Github URL Aman?         : {SsrfGuard.IsSafePublicUrl(safeUrl)} (Ekspektasi: True)");
        Console.WriteLine($"Localhost SSRF Diblokir? : {!SsrfGuard.IsSafePublicUrl(maliciousSsrfUrl)} (Ekspektasi: True)");
        Console.WriteLine($"Cloud Metadata Diblokir? : {!SsrfGuard.IsSafePublicUrl(cloudMetadataUrl)} (Ekspektasi: True)");
    }
}

